import{_ as s}from"./chunks/benchmark.JDxUlm17.js";import{_ as t,o as r,c as n,ai as a}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/benchmark.md","filePath":"fr/guide/benchmark.md"}'),o={name:"fr/guide/benchmark.md"};function i(l,e,u,d,c,p){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to &quot;Benchmark&quot;">​</a></h1><p>La page Benchmark exécute des évaluations standardisées sur vos modèles locaux en utilisant de vrais logprobs de tokens, vous fournissant des données de performance objectives.</p><p><strong>Élément de la barre latérale :</strong> Benchmark <strong>Route :</strong> <code>/benchmark</code></p><p><img src="'+s+'" alt="Interface Benchmark"></p><h2 id="qu-est-ce-que-le-benchmark-chirurgical" tabindex="-1">Qu&#39;est-ce que le Benchmark Chirurgical ? <a class="header-anchor" href="#qu-est-ce-que-le-benchmark-chirurgical" aria-label="Permalink to &quot;Qu&#39;est-ce que le Benchmark Chirurgical ?&quot;">​</a></h2><p>Contrairement aux benchmarks classiques qui vérifient simplement si la réponse est correcte, le Benchmark Chirurgical de LLMxRay capture de <strong>vrais logprobs de tokens</strong> via le endpoint compatible OpenAI d&#39;Ollama (<code>/v1/chat/completions</code>). Cela vous donne des données de confiance authentiques pour chaque réponse, et pas seulement la précision.</p><h2 id="suites-de-tests-integrees" tabindex="-1">Suites de tests intégrées <a class="header-anchor" href="#suites-de-tests-integrees" aria-label="Permalink to &quot;Suites de tests intégrées&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Questions</th><th>Ce qu&#39;elle évalue</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>Raisonnement scientifique</td><td>Questions de sciences niveau collège</td></tr><tr><td><strong>GSM8K</strong></td><td>Problèmes mathématiques</td><td>Raisonnement arithmétique en plusieurs étapes</td></tr><tr><td><strong>HellaSwag</strong></td><td>Complétion de phrases</td><td>Raisonnement de bon sens</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>Multi-disciplines</td><td>Connaissances académiques larges dans différents domaines</td></tr><tr><td><strong>TruthfulQA</strong></td><td>Véracité</td><td>Résistance aux idées reçues erronées</td></tr></tbody></table><h2 id="lancer-un-benchmark" tabindex="-1">Lancer un benchmark <a class="header-anchor" href="#lancer-un-benchmark" aria-label="Permalink to &quot;Lancer un benchmark&quot;">​</a></h2><ol><li>Sélectionnez un <strong>modèle</strong> dans le menu déroulant.</li><li>Choisissez une ou plusieurs <strong>suites de tests</strong>.</li><li>Cliquez sur <strong>Lancer</strong>. Le benchmark diffuse les résultats en temps réel.</li></ol><p>Pendant l&#39;exécution, vous pouvez voir :</p><ul><li><strong>Progression en direct</strong> -- Nombre de questions, précision actuelle</li><li><strong>Résultats par question</strong> -- Correct/incorrect, réponse du modèle, scores de confiance</li><li><strong>Données de latence</strong> -- TTFT et tokens/sec par question</li></ul><h2 id="modeles-de-raisonnement" tabindex="-1">Modèles de raisonnement <a class="header-anchor" href="#modeles-de-raisonnement" aria-label="Permalink to &quot;Modèles de raisonnement&quot;">​</a></h2><p>Pour les modèles de raisonnement comme DeepSeek-R1, le benchmark utilise des <strong>budgets de tokens dynamiques</strong> -- accordant au modèle plus de tokens pour ses blocs <code>&lt;think&gt;</code> sans les compter dans la réponse. Cela garantit que les modèles de raisonnement ne sont pas pénalisés pour avoir montré leur cheminement.</p><h2 id="visualisation-des-resultats" tabindex="-1">Visualisation des résultats <a class="header-anchor" href="#visualisation-des-resultats" aria-label="Permalink to &quot;Visualisation des résultats&quot;">​</a></h2><p>Après complétion, les résultats sont affichés sous forme de :</p><ul><li><strong>Score de précision</strong> -- Pourcentage global de bonnes réponses</li><li><strong>Détail par catégorie</strong> -- Précision par domaine au sein de chaque suite</li><li><strong>Graphique radar</strong> -- Comparaison visuelle entre les catégories</li><li><strong>Distribution de confiance</strong> -- Histogramme des scores de confiance basés sur les logprobs</li></ul><h2 id="comparer-les-resultats" tabindex="-1">Comparer les résultats <a class="header-anchor" href="#comparer-les-resultats" aria-label="Permalink to &quot;Comparer les résultats&quot;">​</a></h2><p>Lancez la même suite sur plusieurs modèles pour comparer :</p><ul><li>Quel modèle est le plus précis sur quels sujets</li><li>Calibration de la confiance -- une confiance élevée correspond-elle à des réponses correctes ?</li><li>Compromis vitesse vs. précision</li></ul><p>Les résultats sont stockés dans IndexedDB, ce qui vous permet de comparer entre les sessions.</p><h2 id="suites-personnalisees" tabindex="-1">Suites personnalisées <a class="header-anchor" href="#suites-personnalisees" aria-label="Permalink to &quot;Suites personnalisées&quot;">​</a></h2><p>Cliquez sur <strong>Importer</strong> pour charger une suite de benchmark personnalisée. Le format attendu est un fichier JSON contenant :</p><ul><li>Nom et description de la suite</li><li>Tableau de questions, chacune avec : texte de la question, choix de réponses, index de la réponse correcte et catégorie optionnelle</li></ul><p>Vous pouvez aussi créer des suites personnalisées directement dans l&#39;application avec le <strong>Constructeur de Suites de Benchmark</strong> — ajoutez des questions manuellement ou laissez un modèle local les générer pour vous. Consultez le <a href="./benchmark-builder.html">guide du Constructeur de Benchmark</a> pour plus de détails.</p><h2 id="exporter-les-resultats" tabindex="-1">Exporter les resultats <a class="header-anchor" href="#exporter-les-resultats" aria-label="Permalink to &quot;Exporter les resultats&quot;">​</a></h2><p>Cliquez sur le bouton <strong>Exporter</strong> dans l&#39;en-tete des resultats pour telecharger vos donnees de benchmark en <strong>JSON</strong>, <strong>CSV</strong> ou <strong>Markdown</strong>. Le JSON inclut les donnees structurees completes pour le scripting et l&#39;analyse ; le CSV fournit des donnees tabulaires plates pour les tableurs ; le Markdown vous donne un rapport formate pret a coller dans vos documents. Consultez le <a href="./export.html">guide d&#39;export</a> pour plus de details sur toutes les options d&#39;export et le partage sur GitHub Discussions.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Les logprobs nécessitent le endpoint <code>/v1</code></strong> -- Cela utilise l&#39;API compatible OpenAI d&#39;Ollama, et non le endpoint natif <code>/api</code>.</li><li><strong>Commencez par des suites plus petites</strong> -- Démarrez avec un sous-ensemble pour estimer la durée d&#39;une exécution complète.</li><li><strong>Reprise possible</strong> -- Si un benchmark est interrompu, vous pouvez reprendre là où il s&#39;est arrêté.</li><li><strong>Comparer les quantifications</strong> -- Lancez le même modèle en Q4 et Q8 pour mesurer l&#39;impact sur la précision.</li></ul>',29)])])}const b=t(o,[["render",i]]);export{g as __pageData,b as default};
